import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 4 · Proactive Personal Agent","description":"Hearth Stage 4 development module: triggers, proactive inbox, mobile PWA, device pairing, push redaction, revocation, attention budgets, and shadow trials.","frontmatter":{"title":"Stage 4 · Proactive Personal Agent","description":"Hearth Stage 4 development module: triggers, proactive inbox, mobile PWA, device pairing, push redaction, revocation, attention budgets, and shadow trials.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4.md","filePath":"en/delivery/stage-4.md","lastUpdated":1793752688000}'),r={name:"en/delivery/stage-4.md"};function n(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<p class="eyebrow">MODULE 4 / 7</p><h1 id="stage-4-·-proactive-personal-agent" tabindex="-1">Stage 4 · Proactive Personal Agent <a class="header-anchor" href="#stage-4-·-proactive-personal-agent" aria-label="Permalink to &quot;Stage 4 · Proactive Personal Agent&quot;">​</a></h1><p class="lead">Let Hearth work proactively within limited authorization while staying quiet. The hard question is not whether it can run automatically, but whether it acts at the right time with the right level of interruption.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Recovery, approval, verification, takeover, and revocation from Stages 1–3 are stable.</li><li>Users have explicit attention budgets, quiet hours, and high-risk action boundaries.</li><li>Proactive mode is controllable, pausable, downgradable, and evaluated against a baseline.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Connect triggers.</strong> Generate events from email, calendar, files, and task dependencies with deduplication, cooldowns, priority, and a &quot;why now&quot; explanation.</li><li><strong>Build the proactive inbox.</strong> Show proactive candidates, suggested actions, budgets, impact, and interruption level; support accept, ignore, pause, and convert to a normal task.</li><li><strong>Deliver the mobile PWA.</strong> Support Today, Needs You, artifacts, approvals, takeover, task creation, and high-signal notifications.</li><li><strong>Complete secure pairing and revocation.</strong> Use short-lived QR pairing, public keys, nonces, parameter binding, expiry, and a secure tunnel or push relay; a lost phone must be revocable immediately.</li><li><strong>Enforce attention budgets.</strong> Limit interruptions, quiet hours, aggregated notifications, background budgets, and runaway loops; start in shadow or control mode.</li><li><strong>Complete the Stage 4 release.</strong> Evaluate proactive success, interruptions per task, satisfaction, budget overruns, and security regressions.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><p>Each increment now has four layers: outcome and gate → four work packages → engineering map and interfaces → acceptance rehearsal. Packages can be split across developers, but merge in dependency order; completing one package does not complete the increment.</p><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-4/d4-1.html">D4.1</a> Triggers and proactive inbox</td><td>Hearth can explain what can be done now</td><td>Event dedupe, candidate generation, A1/A2 boundaries, pause and ignore</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/d4-2.html">D4.2</a> Mobile PWA</td><td>View, approve, take over, and create from a phone</td><td>Responsive PWA, key actions, offline read-only, push redaction</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/d4-3.html">D4.3</a> Secure pairing, push, and revocation</td><td>Pairing is simple and a lost phone can be revoked</td><td>Public-key pairing, nonce, expiry, revocation, audit</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/d4-4.html">D4.4</a> Attention budgets and proactive trial</td><td>Proactive work is quiet and useful</td><td>Interruption metrics, quiet hours, shadow mode, kill switch</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/d4-5.html">D4.5</a> Stage 4 release</td><td>Proactive tasks are useful and key mobile actions work</td><td>Satisfaction, success, budget, and security evaluation</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] Proactive tasks are genuinely useful and do not create notification fatigue.</li><li>[ ] Average interruptions per task are at most one.</li><li>[ ] High-risk actions still require approval; mobile approvals cannot be replayed.</li><li>[ ] A lost device can be revoked and then cannot approve or take over.</li><li>[ ] Users can pause, revoke, and downgrade proactive mode; no runaway loops or budget overruns exist.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Proactive loops without budgets, quiet periods, and revocation.</li><li>Long-lived primary credentials on mobile.</li><li>Notification bodies that leak sensitive information.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-5.html">Stage 5 · Memory &amp; Evolution</a> to accumulate personal context and improve methods safely.</p>',16)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
